async function resend(){if(!email.trim()){setMessage('Önce e-posta adresinizi yazın.');return;}setBusy(true);try{const{error}=await getBrowserClient().auth.resend({type:'signup',email:email.trim(),options:{emailRedirectTo:location.origin+'/auth/callback'+(next?'?next='+encodeURIComponent(next):'')}});setMessage(error?'Doğrulama e-postası gönderilemedi. Biraz sonra yeniden deneyin.':'Doğrulama bağlantısı yenilendi. Gelen kutunuzu kontrol edin.');}catch{setMessage('E-posta isteği tamamlanamadı.');}finally{setBusy(false);}}

